def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    out = g.copy()
    blocks = []
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        if o["size"] == 4 and y1 - y0 == 1 and x1 - x0 == 1:
            blocks.append((y0, x0, y1, x1))
    inside = lambda y, x: 0 <= y < H and 0 <= x < W
    plans = []
    for (y0, x0, y1, x1) in blocks:
        corners = {"TL": (y0-1, x0-1, -1, -1), "TR": (y0-1, x1+1, -1, 1),
                   "BR": (y1+1, x1+1, 1, 1), "BL": (y1+1, x0-1, 1, -1)}
        col = {k: (g[v[0], v[1]] if inside(v[0], v[1]) else None) for k, v in corners.items()}
        # clockwise rotation: TL<-BL, TR<-TL, BR<-TR, BL<-BR
        new = {"TL": col["BL"], "TR": col["TL"], "BR": col["TR"], "BL": col["BR"]}
        for k, (y, x, dy, dx) in corners.items():
            c = new[k]
            if c is None or not inside(y, x):
                continue
            out[y, x] = c
            plans.append((y, x, dy, dx, int(c)))
    emit(out, "Rotated each red block's four corner colours one step clockwise.")

    # corners whose ray has at least one free cell can be joined by other rays
    joinable = {}
    for (y, x, dy, dx, c) in plans:
        yy, xx = y + dy, x + dx
        if inside(yy, xx) and g[yy, xx] == bg:
            joinable[(y, x)] = c

    for i, (y, x, dy, dx, c) in enumerate(plans):
        yy, xx = y + dy, x + dx
        while inside(yy, xx) and g[yy, xx] == bg:
            out[yy, xx] = c
            touch = any(joinable.get((yy + a, xx + b)) == c and (yy + a, xx + b) != (y, x)
                        for a, b in ((1, 0), (-1, 0), (0, 1), (0, -1)))
            if touch:
                break
            yy += dy; xx += dx
        if i % 4 == 3 or i == len(plans) - 1:
            emit(out, "Extended this block's diagonal rays outward until a border, an input object, or joining a same-coloured ray.")
    return out
